{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://anipotts.com/schemas/personal-context-source-v1.json",
  "title": "Personal Context descriptive source metadata and projection vocabulary",
  "description": "Descriptive fields are optional. This contract does not infer collection state, expose private catalog metadata, or authorize collection.",
  "$ref": "#/$defs/source_description",
  "$defs": {
    "source_connectors": {
      "type": "string",
      "enum": ["browsing", "messages", "contacts", "mail", "calendar", "notes", "media", "agent_transcripts", "code", "health", "legacy_vaults", "other"]
    },
    "source_collections": {
      "type": "string",
      "enum": ["live", "one_shot", "discovered"]
    },
    "source_collection_unstated": {
      "const": "unknown",
      "description": "A served sentinel for unspecified collection. It is not a writable collection lifecycle."
    },
    "source_statuses": {
      "type": "string",
      "enum": ["discovered", "unavailable", "pending", "partial", "current", "failed", "excluded", "paused"]
    },
    "source_transports": {
      "type": "string",
      "enum": ["launchd", "push", "manual", "derived"]
    },
    "source_metadata_hosts": {
      "type": "string",
      "description": "Declared source-metadata host subset. Fleet membership remains owned by the entity and machine registries.",
      "enum": ["ap-mini", "ap-pro"]
    },
    "source_metadata_view": {
      "description": "Only these optional catalog metadata keys may be projected to a non-owner reader. Unknown private catalog keys remain unread.",
      "const": ["status", "discovered_count", "excluded_count", "failed_count", "last_success_at", "display_name", "connector", "job", "host", "collection", "transport", "adapter", "held_from", "held_to"]
    },
    "source_derived_fields": {
      "description": "Derived from held records, never merged from descriptive mapping entries.",
      "const": ["held_from", "held_to"]
    },
    "source_description": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "display_name": {"type": "string", "minLength": 1, "pattern": "\\S"},
        "connector": {"$ref": "#/$defs/source_connectors"},
        "job": {"type": "string", "minLength": 1, "pattern": "\\S"},
        "host": {"$ref": "#/$defs/source_metadata_hosts"},
        "collection": {"$ref": "#/$defs/source_collections"},
        "transport": {"$ref": "#/$defs/source_transports"},
        "adapter": {"type": "string", "minLength": 1, "pattern": "\\S"}
      }
    }
  }
}
